(function(){
'use strict';
const app=window.DANA_APP;if(!app||!app.sb||!app.state)return;
const sb=app.sb,state=app.state;
const PRODUCTS=['dulux_emulsion','dulux_oil','leafs_tinting','dulux_polyurethane'];
let voice=null,saving=false,uiTimer=null;
const $=id=>document.getElementById(id);
const esc=v=>app.esc?app.esc(v):String(v??'');
const isRep=()=>state.profile?.role==='rep';
const isManagement=()=>!!state.profile&&!isRep();
const productName=k=>({dulux_emulsion:'إميلشن',dulux_oil:'زيتي',leafs_tinting:'ليفز',dulux_polyurethane:'بولي يوريثان'}[k]||(k?app.productLabel?.(k)||k:'غير محدد'));
const sec=n=>{n=Math.max(0,Math.min(120,Math.round(Number(n)||0)));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
function schedule(fn,ms=80){clearTimeout(uiTimer);uiTimer=setTimeout(fn,ms);}
function ensureStyles(){if($('statusProductSafeStyles'))return;const s=document.createElement('style');s.id='statusProductSafeStyles';s.textContent=`
.sp-safe-inline{grid-column:1/-1;margin:-2px 0 5px}.sp-safe-box{border:1px solid #dbe4ee;border-radius:14px;padding:13px;background:#f8fafc}.sp-safe-box label{display:block;font-weight:900;margin-bottom:7px}.sp-safe-voice-head{display:flex;justify-content:space-between;gap:8px;margin-bottom:9px}.sp-safe-voice-head span{font-size:12px;color:#64748b}.sp-safe-row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.sp-safe-rec{border:0;border-radius:12px;padding:11px 14px;background:#111827;color:#fff;font:inherit;font-weight:900}.sp-safe-rec.recording{background:#b91c1c}.sp-safe-audio{width:min(100%,360px);height:38px;margin-top:9px}.sp-safe-note{margin-top:9px}.sp-safe-note textarea{width:100%;min-height:58px}.sp-safe-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.sp-safe-panel{border:1px solid #dfe5ec;border-radius:15px;padding:13px;background:#f8fafc}.sp-safe-panel h4{margin:0 0 9px}.sp-safe-chips{display:flex;gap:7px;flex-wrap:wrap}.sp-safe-chip{padding:6px 9px;border:1px solid #dbe4ee;border-radius:999px;background:white;font-size:12px;font-weight:800}.sp-safe-panel details{background:#fff;border:1px solid #e5e7eb;border-radius:11px;margin-top:8px;overflow:hidden}.sp-safe-panel summary{cursor:pointer;padding:9px 10px;font-weight:900;display:flex;justify-content:space-between}.sp-safe-list{padding:0 10px 10px}.sp-safe-customer{display:flex;justify-content:space-between;gap:8px;font-size:12px;border-top:1px solid #f1f5f9;padding-top:6px;margin-top:6px}.sp-safe-breakdown{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.sp-safe-breakdown span{font-size:10px;font-weight:800;background:#f8fafc;border:1px solid #e2e8f0;border-radius:999px;padding:4px 6px}@media(max-width:700px){.sp-safe-grid{grid-template-columns:1fr}.sp-safe-row{align-items:stretch}.sp-safe-rec{width:100%}}
`;document.head.appendChild(s);}
function resetVoice(){if(voice){try{if(voice.rec?.state!=='inactive')voice.rec.stop();}catch(_){}try{voice.stream?.getTracks()?.forEach(t=>t.stop());}catch(_){}if(voice.timer)clearInterval(voice.timer);if(voice.url)URL.revokeObjectURL(voice.url);}voice=null;renderVoice('empty');}
function renderVoice(mode){const btn=$('spSafeVoiceBtn'),tm=$('spSafeVoiceTime'),st=$('spSafeVoiceState'),rs=$('spSafeVoiceReset'),au=$('spSafeVoiceAudio');if(!btn)return;if(mode==='recording'){btn.classList.add('recording');btn.textContent='⏹ إيقاف التسجيل';if(st)st.textContent='جاري التسجيل...';rs?.classList.remove('hidden');au?.classList.add('hidden');}else if(mode==='ready'&&voice?.blob){btn.classList.remove('recording');btn.textContent='🎤 إعادة التسجيل';if(tm)tm.textContent=sec(voice.duration);if(st)st.textContent='تم التسجيل — تقدر تسمعه قبل الحفظ';rs?.classList.remove('hidden');if(au){au.src=voice.url;au.classList.remove('hidden');}}else{btn.classList.remove('recording');btn.textContent='🎤 ابدأ التسجيل';if(tm)tm.textContent='00:00';if(st)st.textContent='اذكر سبب التردد أو الرفض بوضوح';rs?.classList.add('hidden');if(au){au.removeAttribute('src');au.classList.add('hidden');}}}
async function toggleVoice(){if(voice?.recording){try{voice.rec.stop();}catch(_){}return;}resetVoice();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return app.flash?.('التسجيل الصوتي غير مدعوم في هذا المتصفح.',true);try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});let mime='';for(const m of ['audio/webm;codecs=opus','audio/webm','audio/mp4']){if(MediaRecorder.isTypeSupported?.(m)){mime=m;break;}}const rec=new MediaRecorder(stream,mime?{mimeType:mime}:undefined),chunks=[];voice={rec,stream,chunks,recording:true,started:Date.now(),duration:0,blob:null,url:null,timer:null};rec.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};rec.onstop=()=>{if(!voice)return;voice.recording=false;voice.duration=Math.max(1,Math.min(120,Math.round((Date.now()-voice.started)/1000)));voice.blob=new Blob(chunks,{type:rec.mimeType||'audio/webm'});voice.url=URL.createObjectURL(voice.blob);stream.getTracks().forEach(t=>t.stop());if(voice.timer)clearInterval(voice.timer);renderVoice('ready');};rec.start(250);voice.timer=setInterval(()=>{if(!voice)return;const n=Math.floor((Date.now()-voice.started)/1000);if($('spSafeVoiceTime'))$('spSafeVoiceTime').textContent=sec(n);if(n>=120){try{voice.rec.stop();}catch(_){}}},500);renderVoice('recording');}catch(_){app.flash?.('تعذر تشغيل المايك. تأكد من صلاحية الميكروفون.',true);}}
async function uploadVoice(){if(!voice?.blob||!voice.duration)throw new Error('voice required');const uid=state.session?.user?.id||state.profile?.id;if(!uid)throw new Error('unauthorized');const ext=(voice.blob.type||'').includes('mp4')?'m4a':'webm',path=`voice/${uid}/initial-status-${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;const {error}=await sb.storage.from('dana-voice-reports').upload(path,voice.blob,{contentType:voice.blob.type||'audio/webm',upsert:false});if(error)throw error;return {path,duration:voice.duration};}
function updateFormState(){const st=$('fStatus')?.value;const v=$('spSafeVoiceBox'),a=$('spSafeAgreementBox');if(v)v.classList.toggle('hidden',!['hesitant','rejected'].includes(st));if(a)a.classList.toggle('hidden',st!=='agreed_pending');if(!['hesitant','rejected'].includes(st)&&voice)resetVoice();}
function decorateCustomerForm(){ensureStyles();const status=$('fStatus');if(!status)return;const field=status.closest('div');if(!field)return;let wrap=$('spSafeStatusWrap');if(!wrap){wrap=document.createElement('div');wrap.id='spSafeStatusWrap';wrap.className='sp-safe-inline full';wrap.innerHTML=`<div id="spSafeVoiceBox" class="sp-safe-box hidden"><div class="sp-safe-voice-head"><b>سبب حالة العميل — تسجيل صوتي</b><span>إلزامي • بحد أقصى دقيقتين</span></div><div class="sp-safe-row"><button type="button" id="spSafeVoiceBtn" class="sp-safe-rec">🎤 ابدأ التسجيل</button><b id="spSafeVoiceTime">00:00</b><span id="spSafeVoiceState" class="small">اذكر السبب بوضوح</span><button type="button" id="spSafeVoiceReset" class="btn secondary mini hidden">حذف وإعادة</button></div><audio id="spSafeVoiceAudio" class="sp-safe-audio hidden" controls></audio><div class="sp-safe-note"><label>تفاصيل إضافية — اختياري</label><textarea id="spSafeVoiceNote" placeholder="ملاحظة إضافية إذا احتجت..."></textarea></div></div><div id="spSafeAgreementBox" class="sp-safe-box hidden"><label>المنتج المتفق عليه</label><select id="spSafeAgreementProduct"><option value=""></option>${PRODUCTS.map(p=>`<option value="${p}">${esc(productName(p))}</option>`).join('')}</select><div class="small">اختر المنتج قبل الحفظ.</div></div>`;field.insertAdjacentElement('afterend',wrap);$('spSafeVoiceBtn')?.addEventListener('click',toggleVoice);$('spSafeVoiceReset')?.addEventListener('click',resetVoice);}else if(field.nextElementSibling!==wrap){field.insertAdjacentElement('afterend',wrap);}const old=$('fInitialReasonWrap');if(old)old.classList.add('hidden');if(!status.dataset.spSafeBound){status.dataset.spSafeBound='1';status.addEventListener('change',updateFormState);}updateFormState();}
async function saveCustomer(e){const btn=e.target.closest?.('#saveCustomerBtn');if(!btn||saving)return;const st=$('fStatus')?.value;if(!['hesitant','rejected','agreed_pending'].includes(st))return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();const name=$('fName')?.value?.trim()||'',type=$('fCustomerType')?.value||'',area=$('fArea')?.value?.trim()||null,phone=$('fPhone')?.value?.trim()||null,latRaw=$('fLat')?.value,lngRaw=$('fLng')?.value,lat=Number(latRaw),lng=Number(lngRaw),rep=$('fRep')?.value||null;if(name.length<2)return app.flash?.('اسم العميل مطلوب.',true);if(!['shop','factory','project'].includes(type))return app.flash?.('حدد نوع العميل.',true);if(isManagement()&&!rep)return app.flash?.('اختر المندوب المسؤول.',true);if(!latRaw||!lngRaw||!Number.isFinite(lat)||!Number.isFinite(lng))return app.flash?.('حدد موقع العميل أولاً.',true);const product=$('spSafeAgreementProduct')?.value||null;if(st==='agreed_pending'&&!product)return app.flash?.('اختر المنتج المتفق عليه.',true);if(['hesitant','rejected'].includes(st)&&(!voice?.blob||!voice.duration))return app.flash?.(st==='hesitant'?'سجل سبب تردد العميل صوتيًا.':'سجل سبب رفض العميل صوتيًا.',true);saving=true;btn.disabled=true;const old=btn.textContent;btn.textContent='جاري الحفظ...';try{let up=null;if(['hesitant','rejected'].includes(st))up=await uploadVoice();const {data,error}=await sb.rpc('create_customer_with_voice_status',{p_name:name,p_area:area,p_phone:phone,p_initial_status:st,p_lat:lat,p_lng:lng,p_assigned_rep:rep,p_customer_type:type,p_audio_path:up?.path||null,p_audio_duration_seconds:up?.duration||null,p_written_note:$('spSafeVoiceNote')?.value?.trim()||null,p_agreement_product:product});if(error)throw error;resetVoice();app.closeModal?.();app.flash?.('تمت إضافة العميل.');await app.refreshAll?.();window.dispatchEvent(new CustomEvent('dana:customer-created',{detail:{customerId:Number(data),source:'status-product-safe'}}));}catch(err){console.error(err);app.flash?.('تعذر حفظ العميل: '+(err?.message||err),true);}finally{saving=false;btn.disabled=false;btn.textContent=old;}}
function decoratePendingAgreement(){const wrap=$('sPendingAgreementWrap');if(!wrap||$('spSafeExistingAgreement'))return;const d=document.createElement('div');d.id='spSafeExistingAgreement';d.className='sp-safe-box';d.innerHTML=`<label>المنتج المتفق عليه</label><select id="spSafeExistingAgreementProduct"><option value=""></option>${PRODUCTS.map(p=>`<option value="${p}">${esc(productName(p))}</option>`).join('')}</select>`;wrap.insertBefore(d,wrap.firstChild);}
async function prepareAgreement(e,btn){if(btn.dataset.spSafePrepared==='1'){delete btn.dataset.spSafePrepared;return false;}const product=$('spSafeExistingAgreementProduct')?.value;if(!product){e.preventDefault();e.stopImmediatePropagation();app.flash?.('اختر المنتج المتفق عليه.',true);return true;}const customerId=Number($('sCustomer')?.value||btn.dataset.customerId||0);if(!customerId)return false;e.preventDefault();e.stopImmediatePropagation();btn.disabled=true;const {error}=await sb.rpc('prepare_customer_agreement',{p_customer_id:customerId,p_product:product});btn.disabled=false;if(error){app.flash?.('تعذر حفظ المنتج المتفق عليه: '+error.message,true);return true;}btn.dataset.spSafePrepared='1';btn.click();return true;}
function latestProductMap(){const m=new Map(),rows=[...(state.sales||[])].sort((a,b)=>String(b.business_date||'').localeCompare(String(a.business_date||''))||String(b.created_at||'').localeCompare(String(a.created_at||'')));for(const s of rows){const id=Number(s.customer_id);if(!m.has(id))m.set(id,s.product||'unknown');}return m;}
function groups(customers,latest){const m=new Map();for(const c of customers){const p=latest.get(Number(c.id))||'unknown';if(!m.has(p))m.set(p,[]);m.get(p).push(c);}return [...m.entries()].sort((a,b)=>b[1].length-a[1].length);}
function repName(c){return c.rep?.full_name||state.profiles?.find(p=>p.id===c.assigned_rep)?.full_name||'-';}
function panel(title,rows,status){return `<div class="sp-safe-panel"><h4>${title}</h4><div class="sp-safe-chips">${rows.length?rows.map(([p,l])=>`<span class="sp-safe-chip">${esc(productName(p))}: <b>${l.length}</b></span>`).join(''):'<span class="small">لا يوجد</span>'}</div>${rows.map(([p,l])=>`<details><summary><span>${status} — ${esc(productName(p))}</span><b>${l.length}</b></summary><div class="sp-safe-list">${l.map(c=>`<div class="sp-safe-customer"><span>${esc(c.name)}</span><span>${esc(repName(c))}${c.area?' · '+esc(c.area):''}</span></div>`).join('')}</div></details>`).join('')}</div>`;}
function inlineBreakdown(target,rows){if(!target)return;let box=target.querySelector('.sp-safe-breakdown');if(!box){box=document.createElement('div');box.className='sp-safe-breakdown';target.appendChild(box);}const html=rows.map(([p,l])=>`<span>${esc(productName(p))}: ${l.length}</span>`).join('');if(box.innerHTML!==html)box.innerHTML=html;}
function renderDashboard(){ensureStyles();const old=$('mgmtProductStatusSafe');if(!state.profile)return;if(!isManagement()){old?.remove();document.querySelectorAll('.sp-safe-breakdown').forEach(x=>x.remove());return;}const latest=latestProductMap(),active=groups((state.customers||[]).filter(c=>c.status==='active'),latest),inactive=groups((state.customers||[]).filter(c=>c.status==='inactive'),latest),cards=$('dashboard')?.querySelector('.dashboard-cards');if(!cards)return;let card=old;if(!card){card=document.createElement('div');card.id='mgmtProductStatusSafe';card.className='card management-only';cards.insertAdjacentElement('afterend',card);}const html=`<div><h3 style="margin:0 0 4px">حالة العملاء حسب المنتج</h3><div class="small" style="margin-bottom:12px">التفصيل يظهر للإدارة فقط. المندوب يشوف نشط أو خامل بدون تفريق.</div></div><div class="sp-safe-grid">${panel('النشطون حسب المنتج',active,'نشط')}${panel('الخاملون حسب المنتج',inactive,'خامل')}</div>`;if(card.innerHTML!==html)card.innerHTML=html;inlineBreakdown($('mActive')?.closest('.metric-card'),active);const dt=$('dormantTitle');if(dt){const parent=dt.parentElement;inlineBreakdown(parent,inactive);}}
function refreshUi(){decorateCustomerForm();decoratePendingAgreement();renderDashboard();}
document.addEventListener('click',async e=>{const save=e.target.closest?.('#saveCustomerBtn');if(save){await saveCustomer(e);return;}const agr=e.target.closest?.('#sSaveAgreedPendingBtn');if(agr){await prepareAgreement(e,agr);return;}if(e.target.closest?.('#newCustomerBtn,[data-quick-action="customer"],[data-add-sale],#sAgreedPendingBtn,[data-page="dashboard"],[data-quick-page="dashboard"]'))schedule(refreshUi,120);},true);
window.addEventListener('dana:render',()=>schedule(refreshUi,60));
window.addEventListener('load',()=>schedule(refreshUi,300));
setTimeout(refreshUi,500);
})();